pub fn release_ready(checks: &[(&str, bool)]) -> bool {
    ["fmt", "test", "build"].iter().all(|required| {
        let rows: Vec<_> = checks
            .iter()
            .filter(|(name, _)| name == required)
            .collect();
        rows.len() == 1 && rows[0].1
    })
}

fn main() {
    assert_eq!(
        release_ready(&[
            ("fmt", true),
            ("test", true),
            ("build", true)
        ]),
        true,
        "case 1"
    );
    assert_eq!(release_ready(&[]), false, "case 2");
    assert_eq!(
        release_ready(&[
            ("fmt", true),
            ("test", false),
            ("build", true)
        ]),
        false,
        "case 3"
    );
    assert_eq!(
        release_ready(&[
            ("fmt", true),
            ("test", true),
            ("build", true),
            ("test", true)
        ]),
        false,
        "case 4"
    );
    assert_eq!(
        release_ready(&[
            ("fmt", true),
            ("test", true),
            ("build", true),
            ("docs", false)
        ]),
        true,
        "case 5"
    );
    println!("worked example passed");
}

